package nodeissuermapping

import (
	"bytes"
	"compress/gzip"
	"context"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"io"
	"reflect"
	"strconv"
	"strings"
	"talenro.local/platform/internal/nodecontrol/contracts"
	"talenro.local/platform/internal/nodecontrol/nodeissuerbinding"
	"testing"
)

type issuerMappingManifest struct {
	Input, Lower, Error string
	Proposed            Projection
}
type issuerMappingOldManifest struct {
	Input                          string
	Raw                            map[string]string
	Lower, Error                   string
	Issuer, Serial                 contracts.Digest
	IssuerPreimage, SerialPreimage string
}

func issuerMappingDecode(t testing.TB, text string, into any) {
	t.Helper()
	b, e := base64.StdEncoding.DecodeString(text)
	if e != nil {
		t.Fatal(e)
	}
	z, e := gzip.NewReader(strings.NewReader(string(b)))
	if e != nil {
		t.Fatal(e)
	}
	defer z.Close()
	b, e = io.ReadAll(z)
	if e != nil {
		t.Fatal(e)
	}
	if e = json.Unmarshal(b, into); e != nil {
		t.Fatal(e)
	}
}
func issuerMappingFixture(t testing.TB, name string) Input {
	t.Helper()
	var packets map[string]Input
	issuerMappingDecode(t, issuerMappingFrozenInputs, &packets)
	in, ok := packets[name]
	if !ok {
		t.Fatal("unknown", name)
	}
	return in
}
func issuerMappingExpected(t testing.TB, name string) issuerMappingManifest {
	var entries map[string]issuerMappingManifest
	issuerMappingDecode(t, issuerMappingFrozenManifest, &entries)
	e, ok := entries[name]
	if !ok {
		t.Fatal(name)
	}
	return e
}
func issuerMappingHash(b []byte) string { d := sha256.Sum256(b); return hex.EncodeToString(d[:]) }
func issuerMappingJSONHash(t testing.TB, v any) string {
	t.Helper()
	b, e := json.Marshal(v)
	if e != nil {
		t.Fatal(e)
	}
	return issuerMappingHash(b)
}
func issuerMappingRawHashes(v reflect.Value, path string, out map[string]string) {
	switch v.Kind() {
	case reflect.Pointer:
		if !v.IsNil() {
			issuerMappingRawHashes(v.Elem(), path, out)
		}
	case reflect.Struct:
		for i := 0; i < v.NumField(); i++ {
			issuerMappingRawHashes(v.Field(i), path+"."+v.Type().Field(i).Name, out)
		}
	case reflect.Slice:
		if v.Type().Elem().Kind() == reflect.Uint8 {
			out[path] = issuerMappingHash(v.Bytes())
			return
		}
		for i := 0; i < v.Len(); i++ {
			issuerMappingRawHashes(v.Index(i), path+"["+strconv.Itoa(i)+"]", out)
		}
	}
}
func assertIssuerMappingLower(t testing.TB, in Input) nodeissuerbinding.Summary {
	t.Helper()
	m, e := nodeissuerbinding.Evaluate(context.Background(), in.Material)
	if m != nil {
		defer m.Clear()
	}
	if e != nil || m == nil {
		t.Fatal("real lower positive control", e)
	}
	return m.Summary()
}
func TestIssuerMappingFixtureControls(t *testing.T) {
	var inputs map[string]Input
	var materials map[string]nodeissuerbinding.Input
	var entries map[string]issuerMappingManifest
	var original map[string]issuerMappingOldManifest
	issuerMappingDecode(t, issuerMappingFrozenInputs, &inputs)
	issuerMappingDecode(t, issuerMappingFrozenMaterials, &materials)
	issuerMappingDecode(t, issuerMappingFrozenManifest, &entries)
	issuerMappingDecode(t, issuerMappingOriginalManifest, &original)
	if len(inputs) != 39 || len(materials) != 39 || len(entries) != 39 || len(original) != 39 {
		t.Fatal("inventory")
	}
	for name, in := range inputs {
		t.Run(name, func(t *testing.T) {
			entry, ok := entries[name]
			if !ok || issuerMappingJSONHash(t, in) != entry.Input || !reflect.DeepEqual(in.Material, materials[name]) || issuerMappingJSONHash(t, in.Material) != original[name].Input {
				t.Fatal("frozen packets")
			}
			raw := map[string]string{}
			issuerMappingRawHashes(reflect.ValueOf(in.Material), "Input", raw)
			if !reflect.DeepEqual(raw, original[name].Raw) {
				t.Fatal("unchanged original raw")
			}
			m, e := nodeissuerbinding.Evaluate(context.Background(), in.Material)
			if m != nil {
				defer m.Clear()
			}
			if entry.Error != "" {
				if m != nil || e == nil || e.Error() != entry.Error {
					t.Fatal("negative", e)
				}
				return
			}
			if e != nil || m == nil {
				t.Fatal(e)
			}
			s := m.Summary()
			if issuerMappingJSONHash(t, s) != entry.Lower || s.Proposed != entry.Proposed.Local {
				t.Fatal("frozen real lower")
			}
			ca, e := x509.ParseCertificate(in.Material.Certificate.CA.DER)
			if e != nil {
				t.Fatal(e)
			}
			leaf, e := x509.ParseCertificate(in.Material.Certificate.Leaf.DER)
			if e != nil {
				t.Fatal(e)
			}
			if leaf.CheckSignatureFrom(ca) != nil || contracts.Digest(sha256.Sum256(ca.Raw)) != in.Claims.Catalog.Entries[0].CADERDigest || contracts.Digest(sha256.Sum256(leaf.Raw)) != in.Claims.Association.LeafDER || contracts.Digest(sha256.Sum256(leaf.RawSubjectPublicKeyInfo)) != in.Claims.Association.PublicKey || !bytes.Equal(leaf.SerialNumber.Bytes(), in.Claims.Association.SerialBytes) {
				t.Fatal("independent x509")
			}
		})
	}
	one := issuerMappingFixture(t, "serial-one-high")
	renewal := issuerMappingFixture(t, "ca-renewal")
	other := issuerMappingFixture(t, "other-ca-same-serial")
	ca, _ := x509.ParseCertificate(one.Material.Certificate.CA.DER)
	re, _ := x509.ParseCertificate(renewal.Material.Certificate.CA.DER)
	if !bytes.Equal(ca.RawSubjectPublicKeyInfo, re.RawSubjectPublicKeyInfo) || !bytes.Equal(ca.RawSubject, re.RawSubject) || bytes.Equal(ca.Raw, re.Raw) || !bytes.Equal(one.Material.Certificate.Leaf.DER, renewal.Material.Certificate.Leaf.DER) || !bytes.Equal(one.Claims.Association.SerialBytes, other.Claims.Association.SerialBytes) {
		t.Fatal("renewal/serial controls")
	}
	for _, name := range []string{"serial-one-high", "serial-twenty"} {
		in := issuerMappingFixture(t, name)
		s := assertIssuerMappingLower(t, in)
		want := 1
		if name == "serial-twenty" {
			want = 20
		}
		if int(s.Evidence.Evidence.Certificate.Leaf.Leaf.SerialLength) != want || len(in.Claims.Association.SerialBytes) != want {
			t.Fatal(name)
		}
	}
}

const issuerMappingFrozenInputs = ""

const issuerMappingFrozenManifest = ""

const issuerMappingFrozenMaterials = ""

const issuerMappingOriginalManifest = ""
